 * hardened-servers.test.ts — the list in `docs/tools/boundaries.md` of the servers
 * that harden themselves, held to the servers that actually do.
 *
 * ## Why this exists
 *
 * The page is prose and the call is code, and nothing connected the two. `attachments`
 * shipped and began calling `hardenCredentialHolder` without ever being added to the
 * list, and the entry for the `atomaton` server was spelled `atoma` — a name no entry
 * in `defaults.yaml` has ever had. Neither is checkable by a reader without running a
 * grep they have no reason to think of, so both survived a release.
 *
 * ## What is read, and what that leaves free
 *
 * `defaults.yaml` says which servers ship; `src/` says which programs harden. The page
 * is then required to name the servers whose program does — not to carry a sentence in
 * a fixed shape, so the prose above and below the list can change freely.
 *
 * `files` is the entry that shows why the `env` blocks are the wrong thing to read.
 * It declares `env: {}` and hardens anyway: hardening does not depend on holding a
 * credential, because a server that ships here makes itself unreadable whether or not
 * its own `env` names anything — `web` is the other one. A rule written from the
 * credentials would therefore be wrong in both directions.
 *
 * ## Why the property is per program and the list is per server
 *
 * `files` and `files_readonly` are one program, started with the same `args`; so are
 * `atomaton` with `atomaton_env`, and `delegate` with `delegate_readonly`. Exactly one
 * entry of each pair is named, and that is the distinction this holds: six entries
 * under `defaults.yaml` reach a program that hardens, and the two names in the list
 * that never harden — `shell` and the three second entries — are what `files` alone
 * would have let through.
 */
import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { toolDefaults } from "../../src/domain/machinery/shipped-servers.ts";

const PAGE = "docs/tools/boundaries.md";

/** The subject of the paragraph the list is in, on the page. */
const MARKER = "Credentials in the servers this project ships";

/** `tools/lib/harden.ts`, as a program that hardens calls it. */
const HARDEN_CALL = /^\s*hardenCredentialHolder\(/m;

/** The server script one `args` entry names, wherever the machinery tree is rooted. */
const SCRIPT_IN_ARG = /(\.github\/atomaton-runtime\/tools\/mcp\/[^"]+)"$/;

/**
 * The shipped servers whose program makes itself unreadable at startup, in the order
 * `defaults.yaml` declares them.
 *
 * Read from the `args` rather than from the entry's name, because the name is what the
 * page uses and the program is what hardens — the two disagree for the three pairs
 * that share a script.
 */
function hardeningServers(): string[] {
  const found: string[] = [];
  for (const [name, server] of Object.entries(toolDefaults().servers)) {
    const args = Array.isArray(server.args) ? server.args.map(String) : [];
    const scripts = args
      .map((arg) => SCRIPT_IN_ARG.exec(arg)?.[1])
      .filter((script): script is string => script !== undefined);
    if (scripts.some((script) => HARDEN_CALL.test(readFileSync(script, "utf8")))) found.push(name);
  }
  return found;
}

/**
 * The server names the page's list holds, in the order it writes them.
 *
 * The paragraph and not the page: `docs/tools/boundaries.md` backticks a dozen other
 * names, and reading those would make the check mean nothing.
 */
function listedServers(page: string): string[] {
  const start = page.indexOf(MARKER);
  if (start < 0) return [];
  const end = page.indexOf("\n\n", start);
  const paragraph = page.slice(start, end < 0 ? undefined : end);
  return [...paragraph.matchAll(/`([a-z_]+)`/g)].map(([, name]) => name!);
}

describe("the hardened servers the page lists", () => {
  const page = readFileSync(PAGE, "utf8");
  const hardening = hardeningServers();
  const listed = listedServers(page);

  test("there are servers to check, either side of the comparison", () => {
    // Six, at the time this was written. A floor rather than the number, because a
    // seventh server is a change to `defaults.yaml` and not a defect here — but a walk
    // that read nothing would make the comparison below pass over an empty list.
    expect(hardening.length).toBeGreaterThanOrEqual(5);
    expect(listed.length, `${PAGE} has no list under "${MARKER}"`).toBeGreaterThan(0);
    expect(new Set(hardening).size, "one program cannot be hardened twice").toBe(hardening.length);
    expect(new Set(listed).size, "the list writes a name twice").toBe(listed.length);
  });

  test("the list names exactly the servers whose program hardens", () => {
    const missing = hardening.filter((name) => !listed.includes(name));
    const extra = listed.filter((name) => !hardening.includes(name));
    expect(
      { missing, extra },
      "the list is the servers that call hardenCredentialHolder at startup. One missing is a " +
        "server that protects itself and is not named; one extra is a name no shipped server " +
        "has, or a second entry of a program already listed — see this file's header for why " +
        "the list is one entry per program",
    ).toEqual({ missing: [], extra: [] });
  });
});
"}

